260→    /// Create a bare git repo with an initial commit containing a template file.
261→    /// Returns the path to the bare repo.
262→    fn create_bare_repo(parent: &Path) -> PathBuf {
263→        let bare_path = parent.join("test-repo.git");
264→
265→        // Create a temporary working directory for the initial commit
266→        let work_dir = parent.join("work");
267→        std::fs::create_dir_all(&work_dir).unwrap();
268→
269→        // Initialize bare repo with explicit default branch
270→        let output = std::process::Command::new("git")
271→            .args([
272→                "init",
273→                "--bare",
274→                "--initial-branch=main",
275→                bare_path.to_string_lossy().as_ref(),
276→            ])
277→            .output()
278→            .unwrap();
279→        assert!(output.status.success(), "bare init failed");
280→
281→        // Clone bare to working dir
282→        let output = std::process::Command::new("git")
283→            .args([
284→                "clone",
285→                bare_path.to_string_lossy().as_ref(),
286→                work_dir.to_string_lossy().as_ref(),
287→            ])
288→            .output()
289→            .unwrap();
290→        assert!(output.status.success(), "clone failed");
291→
292→        // Configure git user for commits
293→        for (key, val) in [("user.name", "Test"), ("user.email", "test@test.com")] {
294→            let output = std::process::Command::new("git")
295→                .args(["config", key, val])
296→                .current_dir(&work_dir)
297→                .output()
298→                .unwrap();
299→            assert!(output.status.success(), "git config {key} failed");
300→        }
301→
302→        // Create a template file and commit
303→        let templates_dir = work_dir.join("templates");
304→        std::fs::create_dir_all(&templates_dir).unwrap();
305→        std::fs::write(
306→            templates_dir.join("node.yml"),
