308→        )
309→        .unwrap();
310→
311→        let output = std::process::Command::new("git")
312→            .args(["add", "."])
313→            .current_dir(&work_dir)
314→            .output()
315→            .unwrap();
316→        assert!(
317→            output.status.success(),
