189→// 6A: Inactive — PATH activation
190→fn handle_inactive(
191→    requirement: &str,
192→    binary_path: &Path,
193→    activation_hint: &str,
194→    checker: &mut GapChecker<'_>,
195→    ctx: &InstallerContext<'_>,
196→) -> Outcome {
197→    if let Some(parent) = binary_path.parent() {
198→        (ctx.prepend_path)(parent);
199→        checker.invalidate(requirement);
200→        Outcome::Resolved
201→    } else {
202→        Outcome::Skip {
203→            reason: format!("'{}' activation failed. {}", requirement, activation_hint),
204→        }
205→    }
206→}
207→
208→// 6B: ServiceDown — offer to start
209→fn handle_service_down(
210→    requirement: &str,
211→    start_command: Option<&str>,
212→    start_hint: &str,
213→    checker: &mut GapChecker<'_>,
214→    ui: &mut dyn UserInterface,
215→    ctx: &InstallerContext<'_>,
216→) -> Outcome {
217→    let Some(cmd) = start_command else {
218→        return Outcome::Skip {
219→            reason: format!("Service '{}' is not running. {}", requirement, start_hint),
220→        };
221→    };
222→
223→    let prompt = Prompt {
224→        key: format!("start_{}", requirement),
225→        question: format!("Start {}? ({})", requirement, cmd),
226→        prompt_type: PromptType::Confirm,
227→        default: Some("yes".to_string()),
228→    };
229→
230→    let confirmed = ui
231→        .prompt(&prompt)
232→        .ok()
233→        .and_then(|r| r.as_bool())
234→        .unwrap_or(false);
235→
236→    if !confirmed {
237→        return Outcome::Skip {
238→            reason: format!("Service '{}' is not running. {}", requirement, start_hint),
239→        };
240→    }
241→
242→    if (ctx.run_command)(cmd) {
243→        checker.invalidate(requirement);
244→        Outcome::Resolved
245→    } else {
246→        Outcome::Skip {
247→            reason: format!("Failed to start '{}'. {}", requirement, start_hint),
248→        }
249→    }
250→}
251→
252→// 6C: Missing — install offer
253→fn handle_missing(
254→    requirement: &str,
255→    install_template: Option<&str>,
256→    install_hint: Option<&str>,
257→    checker: &mut GapChecker<'_>,
258→    ui: &mut dyn UserInterface,
259→    ctx: &InstallerContext<'_>,
260→) -> Outcome {
261→    let hint = install_hint.unwrap_or("Install manually");
262→
263→    if install_template.is_none() {
264→        return Outcome::Skip {
265→            reason: format!("Missing requirement '{}'. {}", requirement, hint),
266→        };
267→    }
268→
269→    if !(ctx.check_network)() {
270→        return Outcome::Skip {
271→            reason: format!(
272→                "Installation of '{}' requires network access, which isn't available.",
273→                requirement
274→            ),
275→        };
276→    }
277→
278→    match checker.resolve_install_deps(requirement) {
279→        Ok(deps) => {
280→            for dep in &deps {
281→                if dep == requirement {
282→                    continue;
283→                }
284→                let dep_status = checker.check_one(dep);
285→                if dep_status.is_satisfied() || dep_status.can_proceed() {
286→                    continue;
287→                }
288→                let dep_prompt = Prompt {
289→                    key: format!("install_{}", dep),
290→                    question: format!("Install dependency '{}'?", dep),
291→                    prompt_type: PromptType::Confirm,
292→                    default: Some("yes".to_string()),
293→                };
294→                let confirmed = ui
295→                    .prompt(&dep_prompt)
296→                    .ok()
297→                    .and_then(|r| r.as_bool())
298→                    .unwrap_or(false);
299→                if !confirmed {
300→                    return Outcome::Skip {
301→                        reason: format!(
302→                            "Dependency '{}' for '{}' not installed.",
303→                            dep, requirement
304→                        ),
305→                    };
306→                }
307→                checker.invalidate(dep);
308→            }
309→        }
310→        Err(e) => {
311→            ui.warning(&format!(
312→                "Could not resolve dependencies for '{}': {}",
313→                requirement, e
314→            ));
315→        }
316→    }
317→
318→    let prompt = Prompt {
319→        key: format!("install_{}", requirement),
320→        question: format!("Install {}?", requirement),
321→        prompt_type: PromptType::Confirm,
322→        default: Some("yes".to_string()),
323→    };
324→
325→    let confirmed = ui
326→        .prompt(&prompt)
327→        .ok()
328→        .and_then(|r| r.as_bool())
329→        .unwrap_or(false);
330→
331→    if !confirmed {
332→        return Outcome::Skip {
333→            reason: format!("Missing requirement '{}'. {}", requirement, hint),
334→        };
335→    }
336→
337→    let install_success = if let Some(hint_cmd) = install_hint {
338→        (ctx.run_command)(hint_cmd)
339→    } else {
340→        false
341→    };
342→
343→    if !install_success {
344→        return Outcome::Skip {
345→            reason: format!(
346→                "Installation of '{}' failed. Check output above.",
347→                requirement
348→            ),
349→        };

  1→//! Cache storage implementation.
  2→
  3→use anyhow::{Context, Result};
  4→use sha2::{Digest, Sha256};
  5→use std::fs;
  6→use std::path::{Path, PathBuf};
  7→
  8→use super::entry::CacheEntry;
  9→
 10→/// Storage for cached templates.
 11→pub struct CacheStore {
 12→    /// Root directory for cache.
 13→    root: PathBuf,
 14→}
 15→
 16→impl CacheStore {
 17→    /// Create a new cache store.
 18→    pub fn new(root: impl Into<PathBuf>) -> Self {
 19→        Self { root: root.into() }
 20→    }
 21→
 22→    /// Get the cache root directory.
 23→    pub fn root(&self) -> &Path {
 24→        &self.root
 25→    }
 26→
 27→    /// Ensure the cache directory exists.
 28→    fn ensure_dir(&self) -> Result<()> {
 29→        fs::create_dir_all(&self.root)
 30→            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
 31→    }
 32→
 33→    /// Get the path for storing an entry's content.
 34→    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 35→        let key = format!("{}:{}", source_id, template_name);
 36→        let hash = Sha256::digest(key.as_bytes());
 37→        let hash_str = hex::encode(&hash[..16]);
 38→        self.root.join(hash_str)
 39→    }
 40→
 41→    /// Get the metadata file path for an entry.
 42→    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 43→        self.content_path(source_id, template_name)
 44→            .with_extension("meta.json")
 45→    }
 46→
 47→    /// Store content and return a cache entry.
 48→    pub fn store(
 49→        &self,
 50→        source_id: &str,
 51→        template_name: &str,
 52→        content: &str,
 53→        ttl_seconds: u64,
 54→    ) -> Result<CacheEntry> {
 55→        self.ensure_dir()?;
 56→
 57→        let content_path = self.content_path(source_id, template_name);
 58→        fs::write(&content_path, content)?;
 59→
 60→        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
 61→            .with_size(content.len() as u64);
 62→
 63→        self.save_metadata(&entry)?;
 64→
 65→        Ok(entry)
 66→    }
 67→
 68→    /// Load a cached entry's metadata.
 69→    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
 70→        let meta_path = self.metadata_path(source_id, template_name);
 71→
 72→        if !meta_path.exists() {
 73→            return Ok(None);
 74→        }
 75→
 76→        let json = fs::read_to_string(&meta_path)?;
 77→        let entry: CacheEntry = serde_json::from_str(&json)?;
 78→
 79→        Ok(Some(entry))
 80→    }
 81→
 82→    /// Read the cached content.
 83→    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
 84→        fs::read_to_string(&entry.content_path).with_context(|| {
 85→            format!(
 86→                "Failed to read cached content from {:?}",
 87→                entry.content_path
 88→            )
 89→        })
 90→    }
 91→
 92→    /// Save entry metadata.
 93→    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
 94→        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
 95→        let json = serde_json::to_string_pretty(entry)?;
 96→        fs::write(&meta_path, json)?;
 97→        Ok(())
 98→    }
 99→
100→    /// Update an entry's metadata (e.g., after revalidation).
101→    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
102→        self.save_metadata(entry)
103→    }
104→
105→    /// Remove a cached entry.
106→    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
107→        let content_path = self.content_path(source_id, template_name);
108→        let meta_path = self.metadata_path(source_id, template_name);
109→
110→        let mut removed = false;
111→
112→        if content_path.exists() {
113→            fs::remove_file(&content_path)?;
114→            removed = true;
115→        }
116→
117→        if meta_path.exists() {
118→            fs::remove_file(&meta_path)?;
119→            removed = true;
120→        }
121→
122→        Ok(removed)
123→    }
124→
125→    /// List all cached entries.
126→    pub fn list(&self) -> Result<Vec<CacheEntry>> {
127→        self.ensure_dir()?;
128→
129→        let mut entries = Vec::new();
130→
131→        for entry in fs::read_dir(&self.root)? {
132→            let entry = entry?;
133→            let path = entry.path();
134→
135→            if path.extension().is_some_and(|e| e == "json") {
136→                if let Ok(json) = fs::read_to_string(&path) {
137→                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
138→                        entries.push(cache_entry);
139→                    }
140→                }
141→            }
142→        }
143→
144→        entries.sort_by(|a, b| b.metadata.cached_at.cmp(&a.metadata.cached_at));
145→        Ok(entries)
146→    }
147→
148→    /// Clear all cached entries.
149→    pub fn clear(&self) -> Result<usize> {
150→        let entries = self.list()?;
151→        let count = entries.len();
152→
153→        for entry in entries {
154→            let _ = self.remove(&entry.source_id, &entry.template_name);
155→        }
156→
157→        Ok(count)
158→    }
159→
160→    /// Get total cache size in bytes.
161→    pub fn total_size(&self) -> Result<u64> {
162→        let entries = self.list()?;
163→        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
164→    }
165→}
