            .filter_map(|e| e.ok())
            .filter(|e| {
                e.path()
                    .to_string_lossy()
                    .contains(".tmp")
            })
            .collect();

        assert!(
            tmp_files.is_empty(),
            "No temp files should remain after write_content"
        );
    }

