/// Write data to a file atomically using a temp file and rename.
///
/// Writes to a temporary file in the same directory, then renames it
/// to the final path. This prevents readers from seeing partial writes
/// and avoids corruption when concurrent writers target the same path.
fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
    let temp_path = path.with_extension(
        path.extension()
            .map(|e| format!("{}.tmp", e.to_string_lossy()))
            .unwrap_or_else(|| "tmp".to_string()),
    );
    fs::write(&temp_path, data)
        .with_context(|| format!("Failed to write temp file {:?}", temp_path))?;
    fs::rename(&temp_path, path)
        .with_context(|| format!("Failed to rename {:?} to {:?}", temp_path, path))?;
    Ok(())
}

input.new_string:
/// Write data to a file atomically using a temp file and rename.
///
/// Writes to a uniquely-named temporary file in the same directory,
/// then renames it to the final path. This prevents readers from
/// seeing partial writes and avoids corruption when concurrent
/// writers target the same path.
fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
    let id = TEMP_COUNTER.fetch_add(1, Ordering::Relaxed);
    let pid = std::process::id();
    let name = path
        .file_name()
        .unwrap_or_default()
        .to_string_lossy();
    let temp_path = path.with_file_name(format!(".{}.{}.{}.tmp", name, pid, id));
    fs::write(&temp_path, data)
        .with_context(|| format!("Failed to write temp file {:?}", temp_path))?;
    fs::rename(&temp_path, path).with_context(|| {
        // Clean up the temp file on rename failure
        let _ = fs::remove_file(&temp_path);
        format!("Failed to rename {:?} to {:?}", temp_path, path)
    })?;
    Ok(())
}

