                    .store("http:test", "shared-key", &content, 3600)
                    .unwrap();
            }));
        }

        for handle in handles {
            handle.join().unwrap();
        }

        // After all threads complete, the entry must be loadable and consistent
        let entry = store.load("http:test", "shared-key").unwrap();
        assert!(entry.is_some(), "Entry should exist after concurrent stores");

        let entry = entry.unwrap();
        let content = store.read_content(&entry).unwrap();

        // Content must start with "content-from-thread-" (not be corrupted/interleaved)
        assert!(
            content.starts_with("content-from-thread-"),
            "Content should not be corrupted: {:?}",
            content
        );

        // Size in metadata must match actual content length
        assert_eq!(
            entry.metadata.size_bytes,
            content.len() as u64,
            "Metadata size must match actual content size"
        );

        // No temp files should remain
        let tmp_files = has_tmp_files(temp.path());
        assert!(
            tmp_files.is_empty(),
            "No temp files should remain after concurrent stores"
        );
    }

    #[test]
    fn concurrent_stores_to_different_keys() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let store = Arc::new(CacheStore::new(temp.path()));

        let mut handles = Vec::new();

        // Spawn threads writing to different keys simultaneously
        for i in 0..10 {
            let store = Arc::clone(&store);
            let key = format!("template-{}", i);
            let content = format!("content-{}", i);
            handles.push(thread::spawn(move || {
                store
                    .store("http:test", &key, &content, 3600)
                    .unwrap();
            }));
        }

        for handle in handles {
            handle.join().unwrap();
        }

        // All 10 entries should exist and be consistent
        for i in 0..10 {
            let key = format!("template-{}", i);
            let expected_content = format!("content-{}", i);

            let entry = store.load("http:test", &key).unwrap();
            assert!(entry.is_some(), "Entry {} should exist", key);

            let entry = entry.unwrap();
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, expected_content);
            assert_eq!(entry.metadata.size_bytes, expected_content.len() as u64);
        }
    }

    #[test]
    fn write_content_is_atomic() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        // First store an entry
        let entry = store
            .store("http:test", "template1", "original", 3600)
            .unwrap();

        // Update just the content via dedicated method
        store
            .write_content(&entry, "updated content")
            .unwrap();

        let content = store.read_content(&entry).unwrap();
        assert_eq!(content, "updated content");

        // No temp files should remain
        let tmp_files = has_tmp_files(temp.path());
        assert!(
            tmp_files.is_empty(),
            "No temp files should remain after write_content"
        );
    }

    #[test]
    fn metadata_update_is_atomic() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let mut entry = store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        entry.metadata.etag = Some("\"new-etag\"".to_string());
        store.update(&entry).unwrap();

        // Reload and verify
        let loaded = store.load("http:test", "template1").unwrap().unwrap();
        assert_eq!(loaded.metadata.etag, Some("\"new-etag\"".to_string()));

        // No temp files should remain
        let tmp_files = has_tmp_files(temp.path());
        assert!(
            tmp_files.is_empty(),
            "No temp files should remain after metadata update"
        );
    }
}

