 24→    }
 25→
 26→    /// Get the cache root directory.
 27→    pub fn root(&self) -> &Path {
 28→        &self.root
 29→    }
 30→
 31→    /// Ensure the cache directory exists.
 32→    fn ensure_dir(&self) -> Result<()> {
 33→        fs::create_dir_all(&self.root)
 34→            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
 35→    }
 36→
 37→    /// Get the path for storing an entry's content.
 38→    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 39→        let key = format!("{}:{}", source_id, template_name);
 40→        let hash = Sha256::digest(key.as_bytes());
 41→        let hash_str = hex::encode(&hash[..16]);
 42→        self.root.join(hash_str)
 43→    }
 44→
 45→    /// Get the metadata file path for an entry.
 46→    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
 47→        self.content_path(source_id, template_name)
 48→            .with_extension("meta.json")
 49→    }
 50→
 51→    /// Write data to a file atomically using a temp file and rename.
 52→    ///
 53→    /// Writes to a uniquely-named temporary file in the same directory,
 54→    /// then renames it to the final path. This prevents readers from
 55→    /// seeing partial writes and avoids corruption when concurrent
 56→    /// writers target the same path.
 57→    fn atomic_write(path: &Path, data: &[u8]) -> Result<()> {
 58→        let id = TEMP_COUNTER.fetch_add(1, Ordering::Relaxed);
 59→        let pid = std::process::id();
 60→        let name = path
 61→            .file_name()
 62→            .unwrap_or_default()
 63→            .to_string_lossy();
 64→        let temp_path = path.with_file_name(format!(".{}.{}.{}.tmp", name, pid, id));
 65→        fs::write(&temp_path, data)
 66→            .with_context(|| format!("Failed to write temp file {:?}", temp_path))?;
 67→        fs::rename(&temp_path, path).with_context(|| {
 68→            // Clean up the temp file on rename failure
 69→            let _ = fs::remove_file(&temp_path);
 70→            format!("Failed to rename {:?} to {:?}", temp_path, path)
 71→        })?;
 72→        Ok(())
 73→    }
