 75→    /// Store content and return a cache entry.
 76→    pub fn store(
 77→        &self,
 78→        source_id: &str,
 79→        template_name: &str,
 80→        content: &str,
 81→        ttl_seconds: u64,
 82→    ) -> Result<CacheEntry> {
 83→        self.ensure_dir()?;
 84→
 85→        let content_path = self.content_path(source_id, template_name);
 86→        Self::atomic_write(&content_path, content.as_bytes())?;
 87→
 88→        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
 89→            .with_size(content.len() as u64);
 90→
 91→        self.save_metadata(&entry)?;
 92→
 93→        Ok(entry)
 94→    }
