 96→    /// Load a cached entry's metadata.
 97→    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
 98→        let meta_path = self.metadata_path(source_id, template_name);
 99→
100→        if !meta_path.exists() {
101→            return Ok(None);
102→        }
103→
104→        let json = fs::read_to_string(&meta_path)?;
105→        let entry: CacheEntry = serde_json::from_str(&json)?;
106→
107→        Ok(Some(entry))
108→    }
109→
110→    /// Read the cached content.
111→    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
112→        fs::read_to_string(&entry.content_path).with_context(|| {
