114→                "Failed to read cached content from {:?}",
115→                entry.content_path
116→            )
117→        })
118→    }
119→
120→    /// Save entry metadata atomically.
121→    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
122→        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
123→        let json = serde_json::to_string_pretty(entry)?;
124→        Self::atomic_write(&meta_path, json.as_bytes())
125→    }
126→
127→    /// Write content to a cache entry atomically.
128→    pub fn write_content(&self, entry: &CacheEntry, content: &str) -> Result<()> {
129→        Self::atomic_write(&entry.content_path, content.as_bytes())
130→    }

